"""Build the complete standalone visual reference. No third-party dependencies."""
from pathlib import Path
import json,html,re
P=Path(__file__).resolve().parent
T=json.loads((P/'tokens.json').read_text());C=T['color']
E=html.escape
sections=[]
def section(id,title,group,desc,body):
    sections.append((id,title,group,f'<section class="board" id="{id}"'+('' if id=='overview' else ' hidden')+f'><header class="board-head"><span class="cs-eyebrow">{E(group)} / {len(sections)+1:02}</span><h1>{E(title)}</h1><p>{E(desc)}</p></header>{body}</section>'))
def heading(k,title,desc=''):
    return f'<div class="section-head"><span class="cs-eyebrow">{E(k)}</span><h2>{E(title)}</h2>'+ (f'<p>{E(desc)}</p>' if desc else '')+'</div>'
def specimen(title,body,note=''):
    return '<div class="specimen"><h3>'+title+'</h3>'+body+(f'<div class="spec-label">{note}</div>' if note else '')+'</div>'
def button(text,extra='',kind='primary'):
    return f'<button class="cs-button cs-button-{kind}" {extra}>{text}</button>'
def swatches(keys):
    return '<div class="palette-grid">'+''.join(f'<div class="swatch"><div class="swatch-surface" style="background:{C[k]}"><span></span><button class="copy-chip" data-copy="{C[k]}" aria-label="Copy {k} color">Copy</button></div><div class="swatch-meta"><strong>{E(k)}</strong><code>{C[k].upper()}</code></div></div>' for k in keys)+'</div>'
def rows(data):
    return '<div class="table-wrap"><table class="data-table">'+''.join('<tr>'+''.join(f'<{"th" if i==0 else "td"}>{cell}</{"th" if i==0 else "td"}>' for cell in row)+'</tr>' for i,row in enumerate(data))+'</table></div>'
def lum(h):
    a=[int(h[i:i+2],16)/255 for i in (1,3,5)];a=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in a];return sum(x*y for x,y in zip(a,[.2126,.7152,.0722]))
def contrast(a,b):
    x,y=sorted([lum(a),lum(b)]);return (y+.05)/(x+.05)

section('overview','A complete system, in one place.','START HERE','The visual language behind Callstorm: cream canvas, olive actions, pastel meaning, and a clear path from a question to its evidence.',
'''<div class="cs-summary"><div class="grid g3"><div><span class="cs-eyebrow">CALLSTORM CALM</span><h2 style="font-size:28px;font-weight:400;line-height:1.2;margin:12px 0">Quiet by default.<br>Clear when it matters.</h2><span class="cs-badge">Visual reference · v1.1</span></div><div><span class="cs-caption">A portable foundation</span><p style="font-size:22px;line-height:1.3">Web, React Native,<br>and Flutter.</p></div><div><span class="cs-caption">Everything is included</span><p style="font-size:16px">Foundations, controls, states, charts, full screens, and downloadable tokens.</p></div></div></div>'''+heading('PRINCIPLES','Four rules that carry the style.')+'<div class="grid g4">'+''.join(specimen(title,f'<p>{body}</p>') for title,body in [('Quiet surfaces','Use the warm canvas for breathing room and white for the area where work happens.'),('Purposeful emphasis','Dark olive identifies the action. Pastels support categories and context.'),('Regular typography','Create hierarchy through size and spacing, with limited bold emphasis.'),('Progressive disclosure','Keep the current decision clear. Open secondary evidence when it is needed.')])+'</div>'+heading('EXPLORE','From individual tokens to complete screens.')+'<div class="grid g3" id="coverage"></div>'+heading('BALANCE','Most of the screen should stay quiet.')+'<div class="ratio-band"><span style="width:80%;background:#eeeee8">80% neutral</span><span style="width:15%;background:#dbc5e2">15%</span><span style="width:5%;background:#343e29;color:white">5%</span></div><p class="tip">An approximate composition guide: neutral surfaces, supporting tint, strong emphasis. Adapt to the task instead of enforcing a pixel quota.</p><div class="cs-notice">This catalog is comprehensive on purpose. In an actual app, show only the components and information needed for the current task.</div>')

surface=['canvas','surface','sidebar','surface-detail','summary','summary-border'];ink=['ink','text-secondary','text-caption','muted-original'];actions=['action','action-hover','on-action','focus','selection','selection-text','border','border-strong']
body=heading('SURFACES','A cream canvas, with white work areas.')+swatches(surface)+heading('TEXT','Dark enough to read, quiet enough to support.')+'<div class="specimen">'+''.join(f'<div class="role-row"><i class="role-chip" style="background:{C[k]}"></i><div>{k}<small>'+('Historical reference; use semantic text roles for new work.' if k=='muted-original' else 'Reusable foreground role')+f'</small></div><code>{C[k].upper()}</code></div>' for k in ink)+'</div>'+heading('INTERACTION & STRUCTURE','Olive acts. Borders organize.')+swatches(actions)+heading('SEMANTIC STATES','Every state pairs a tint with a readable foreground.')+'<div class="grid g4">'+''.join(f'<div class="specimen" style="background:{C[k+"-surface"]};color:{C[k+"-text"]}"><h3>{label}</h3><p style="color:inherit">{text}</p><code style="font-size:12px">{C[k+"-surface"]}<br>{C[k+"-text"]}</code><p style="color:inherit">{contrast(C[k+"-surface"],C[k+"-text"]):.2f}:1 contrast</p></div>' for k,label,text in [('success','✓ Completed','The operation finished.'),('warning','! Needs review','A limit was exceeded.'),('danger','× Could not save','Fix the issue and retry.'),('info','i Context','Useful supporting detail.')])+'</div>'+heading('REMAINING ROLES','Accent and disabled colors.')+swatches(['olive','lime','blue','lavender','peach','warm','disabled-surface','disabled-text'])+'<p class="tip">The darker reusable text and control roles are documented adaptations of the original dashboard. Contrast values here describe color pairs, not full-screen accessibility certification.</p>'
section('color','Color','FOUNDATIONS','Every core color, its role, and its value. Copy a swatch to reuse the exact hex value.',body)

families={'Blue':['#e8eff7','#c6dcfa','#607da2','#3e5877'],'Lavender':['#eee6f0','#dbc5e2','#8a6698','#51465b'],'Peach':['#fae9d7','#f7d1a8','#897047','#624d34']}
options={'Rose':['#f8e8ec','#f4c6d3','#d094a6','#6a4751'],'Coral':['#f9e9e5','#fcc6b8','#d29788','#6b4940'],'Butter':['#f8f4de','#f5e9b0','#baac68','#5a5332'],'Mint':['#e2f1ea','#c0e9d6','#7ab79c','#375b4c'],'Aqua':['#e0f1f1','#b9e4e6','#6bb6ba','#2e5b5d'],'Sky':['#e1f0f6','#c2e4f4','#74b1cd','#335868'],'Periwinkle':['#ebebf9','#cdcdf1','#a2a2d6','#4f4f6d'],'Mauve':['#f6e8ef','#dfc1d0','#ba90a7','#674759']}
(P/'reference/pastel-options.json').write_text(json.dumps({'description':'Optional palette candidates transcribed from the user-provided design-system.zip reference. Not part of the core theme.','families':{k:dict(zip(['tint','fill','stroke','ink'],v)) for k,v in options.items()}},indent=2)+'\n')
def family_card(k,v):
    return specimen(k,'<div class="tone-row">'+''.join(f'<div style="background:{h};color:{(v[3] if contrast(h,v[3])>=4.5 else ("#20211e" if contrast(h,"#20211e")>=4.5 else "white"))}">{["Tint","Fill","Stroke","Ink"][i]}<code>{h}</code></div>' for i,h in enumerate(v))+'</div>'+f'<div class="tint-example" style="background:{v[0]};color:{v[3]}"><span class="pill" style="background:{v[1]}">Category label</span><p>Supporting context stays readable.</p></div>',f'Ink on tint · {contrast(v[0],v[3]):.2f}:1')
section('pastels','Pastel families & options','FOUNDATIONS','See colors as a small family of tint, fill, stroke, and ink—not an isolated swatch.',heading('CORE DIRECTION','The three supporting families.')+'<div class="grid g3">'+''.join(family_card(k,v) for k,v in families.items())+'</div><p class="tip">The core examples use the reusable chart strokes. Lavender tint and ink are supporting examples from the original direction; the authoritative token roles remain in the token explorer.</p>'+heading('OPTIONAL EXTENSIONS','Eight options from your supplied reference.','These are candidates for new category needs. They do not replace the core palette or silently enter the generated app themes.')+'<div class="grid g2">'+''.join(family_card(k,v) for k,v in options.items())+'</div>'+heading('USE WITH INTENT','Choose a small set and keep labels visible.')+'<div class="grid g2">'+specimen('A small extension','<div class="tone-row">'+''.join(f'<div style="background:{h}"></div>' for h in [C['blue'],C['lavender'],C['peach'],options['Rose'][1],options['Mint'][1]])+'</div><p>Blue, lavender, peach, rose, mint. Useful when five categories need a soft distinction.</p>')+specimen('A larger extension','<div class="tone-row">'+''.join(f'<div style="background:{h}"></div>' for h in [C['blue'],C['lavender'],C['peach'],options['Rose'][1],options['Butter'][1],options['Aqua'][1]])+'</div><p>Blue, lavender, peach, rose, butter, aqua. Still pair color with labels, symbols, or line styles.</p>')+'</div>')

body=heading('TYPE SCALE','Regular weight. Deliberate hierarchy.')+'<div class="specimen">'+''.join(f'<div class="type-sample"><div class="type-info">{k}<br>{v["size"]} px / {v["weight"]}<br>line {v["lineHeight"]} · track {v["tracking"]}</div><div class="type-text" style="font-size:{v["size"]}px;line-height:{v["lineHeight"]};letter-spacing:{v["tracking"]}px;'+('font-family:monospace;' if k=='eyebrow' else '')+'">'+{'page':'A clearer picture of your agent.','insight':'Stay at 20 concurrent calls.','section':'What would you like to understand?','card':'Where does the agent lose the task?','body':'Read the result, understand the context, and choose the next step.','label':'Compare with the previous run','caption':'1,000 synthetic calls · same scenario mix','eyebrow':'EXPLORE THE EVIDENCE','metric':'94.2%'}[k]+'</div></div>' for k,v in T['typography']['styles'].items())+'</div>'+heading('TYPE IN CONTEXT','Size and spacing do most of the work.')+'<div class="grid g2">'+specimen('A complete text stack','<span class="cs-eyebrow">SELECTED FINDING</span><h2 style="font-weight:400;font-size:25px;line-height:1.2;letter-spacing:-.7px">Interruptions need the most work.</h2><p>Review the caller’s corrected intent before deciding whether the task passed.</p><span class="cs-caption">Selected run · illustrative evidence</span>')+specimen('Test the reading size','<label class="type-size-slider" for="readingSize">Body size <input id="readingSize" type="range" min="16" max="32" value="16"><output id="readingSizeValue">16 px</output></label><p id="readingSample" style="font-size:16px">The interface should remain comfortable when people increase the text size.</p><p>Web: Arial, Helvetica, sans-serif.<br>Native: system sans with text scaling enabled.</p>')+'</div>'+heading('NUMBERS','Use stable numeric alignment.')+specimen('Metrics and units','<div class="grid g3"><div><span class="cs-metric">20 <small>calls</small></span></div><div><span class="cs-metric">1.18 <small>s</small></span></div><div><span class="cs-metric">$0.084</span></div></div>','Tabular numerals · units secondary · context always visible')
section('type','Typography','FOUNDATIONS','All nine text styles, paired with examples that show how they work together.',body)

body=heading('SPACING','A small scale, applied consistently.')+'<div class="grid g2">'+specimen('Spacing scale',''.join(f'<div class="space-measure"><span>{k} px</span><i style="width:{max(1,v*4)}px"></i></div>' for k,v in T['space'].items()),'Logical pixels; rem on web, dp/points on native')+specimen('Inside a card','<div class="dimensions"><div class="dimension-tag">24 px<br>card<br>padding</div><div class="inner"><span class="cs-eyebrow">8–12 PX INLINE GAP</span><h3 style="margin-top:12px">Related content stays together.</h3><p>Use 24 px inside a card and 32–40 px between sections.</p></div></div><p>Desktop inset: 40 px<br>Tablet inset: 24 px<br>Mobile inset: 16 px</p>')+'</div>'+heading('RADIUS','The larger the surface, the softer the corner.')+'<div class="grid g3">'+''.join(specimen(k,f'<div class="shape-sample" style="border-radius:{v}px">{v if v<999 else "Full"} px</div>') for k,v in T['radius'].items())+'</div>'+heading('DEPTH','Flat surfaces; elevated overlays.')+'<div class="grid g3">'+specimen('Card','<div class="cs-card">A thin border defines the edge.</div>','No default shadow')+specimen('Detail well','<div class="cs-observation">A quiet tint keeps related evidence together.</div>','Nested radius · low emphasis')+specimen('Overlay','<div class="cs-card" style="box-shadow:0 12px 32px #29302020">Covers the current context.</div>','Shadow reserved for layering')+'</div>'+heading('LAYOUT DIMENSIONS','The screen adapts before the text shrinks.')+rows([['Role','Value','Use']]+[[k,str(v)+' px',{'sidebar':'Wide navigation','compactRail':'Compact navigation','topbar':'Desktop header','detailPanel':'Interpretation column','drawer':'Desktop evidence panel','contentMax':'Content width limit','controlWeb':'Minimum web control height','controlMobile':'Minimum native/touch control height','icon':'Standard icon size'}[k]] for k,v in T['size'].items()])
section('space','Space, shape & depth','FOUNDATIONS','Reusable spacing and geometry, with the original dashboard’s recognizable proportions.',body)

body=heading('ACTIONS','One main action. Quiet alternatives.')+'<div class="grid g2">'+specimen('Button hierarchy','<div class="control-row">'+button('Primary action','data-toast="Primary action selected"')+button('Secondary','data-toast="Secondary action selected"','secondary')+button('Text action ↗','data-toast="Text action selected"','text')+'</div>','44 px web · 48 px touch · 6 px radius')+specimen('State specimens','<div class="control-row">'+button('Hover','style="background:var(--cs-action-hover)" data-toast="Hover specimen"')+button('Focus','class="sample-focus" data-toast="Focus specimen"','secondary')+button('Disabled','disabled')+button('Try loading','id="loadingButton"')+'</div>','Hover/focus labeled specimens; loading is interactive')+'</div>'+heading('FIELDS','Labels persist. Errors explain the recovery.')+'<div class="grid g2">'+specimen('Inputs','<form id="demoForm" class="field-stack" novalidate><div><label class="cs-label" for="workspaceName">Workspace name</label><input id="workspaceName" class="cs-input" placeholder="Engineering" aria-describedby="workspaceError"><p id="workspaceError" class="cs-error" hidden></p></div><div><label class="cs-label" for="workspaceType">Workspace type</label><select class="cs-input" id="workspaceType"><option>Engineering</option><option>Product</option><option>Research</option></select></div>'+button('Save example','type="submit"')+'<p id="formMessage" role="status"></p></form>')+specimen('Input variants','<div class="field-stack"><div><label class="cs-label" for="inputFilled">Filled</label><input id="inputFilled" class="cs-input" value="Customer support"></div><div><label class="cs-label" for="inputInvalid">Error</label><input id="inputInvalid" class="cs-input" aria-invalid="true" aria-describedby="inputError" value=""><p class="cs-error" id="inputError">A project name is required.</p></div><div><label class="cs-label" for="inputDisabled">Disabled</label><input id="inputDisabled" class="cs-input" value="Managed by the workspace" disabled></div><div><label class="cs-label" for="inputNotes">Notes</label><textarea id="inputNotes" class="cs-input" rows="2" placeholder="Add useful context"></textarea></div></div>')+'</div>'+heading('CHOICES','Native behavior, with a consistent visual treatment.')+'<div class="grid g3">'+specimen('Checkbox & radio','<label class="check-row"><input type="checkbox" checked>Show previous run</label><label class="check-row"><input type="checkbox">Include archived runs</label><label class="check-row"><input type="radio" name="suite" checked>Regression suite</label><label class="check-row"><input type="radio" name="suite">Load sweep</label>')+specimen('Switch & range','<div class="toggle-row"><span id="alertsLabel">Email alerts</span><button class="switch" role="switch" aria-checked="true" aria-labelledby="alertsLabel"><i></i></button></div><label class="cs-label" for="budgetRange">Response budget <output id="budgetValue">1.0 s</output></label><input id="budgetRange" type="range" min="5" max="20" value="10" style="width:100%;accent-color:var(--cs-olive)">')+specimen('Menu & disclosure','<details><summary class="cs-label" style="cursor:pointer;min-height:44px">Run actions</summary><div class="cs-stack">'+button('Compare run','data-toast="Comparison example selected"','secondary')+button('Download example','data-download="tokens.json"','secondary')+'</div></details><details><summary style="font-size:14px;cursor:pointer;margin-top:20px">What does P95 mean?</summary><p>95% of measured responses are at or below this duration.</p></details>')+'</div>'+heading('NAVIGATION','A selected state that is visible without shouting.')+'<div class="grid g2">'+specimen('Side navigation','<div class="sample-nav"><button aria-pressed="true">Overview</button><button aria-pressed="false">Evaluation runs</button><button aria-pressed="false">Conversations</button></div><p id="sampleNavStatus">Overview selected</p>')+specimen('Breadcrumbs & local tabs','<div class="sample-crumbs">Workspace <span>/</span> Refund agent</div><div class="cs-tabs" style="margin-top:20px" role="tablist" aria-label="Component example tabs"><button class="cs-tab local-tab" role="tab" aria-selected="true" tabindex="0" data-local="Latency">Latency</button><button class="cs-tab local-tab" role="tab" aria-selected="false" tabindex="-1" data-local="Quality">Quality</button><button class="cs-tab local-tab" role="tab" aria-selected="false" tabindex="-1" data-local="Cost">Cost</button></div><p id="localTabContent" role="status">Latency content selected.</p>')+'</div>'+heading('SMALL ELEMENTS','Badges, avatars, and icons.')+'<div class="grid g2">'+specimen('Badges & avatars','<div class="control-row"><span class="cs-badge cs-badge-success">✓ Passed</span><span class="cs-badge cs-badge-warning">! Review</span><span class="cs-badge cs-badge-danger">× Failed</span><span class="cs-badge">Demo data</span><span style="display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:var(--cs-lavender)">YG</span></div>')+specimen('Line icons','<div class="icon-samples">'+''.join(f'<div class="icon-sample"><svg viewBox="0 0 24 24" role="img" aria-label="{label}"><path d="{path}"/></svg></div>' for label,path in [('Home','M3 10l9-7 9 7v10H3z M9 20v-7h6v7'),('Chart','M4 3v17h17 M8 15V9 M13 15V5 M18 15v-5'),('Search','M16 16l5 5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0'),('Arrow','M5 19L19 5 M7 5h12v12')])+'</div>','20–24 px · 1.7 px stroke · accessible labels')+'</div>'
