linechart='''<div class="chart-wrap"><svg id="loadChart" viewBox="0 0 680 285" role="img" aria-label="P95 response time at six tested concurrency levels"><g id="loadPlot"></g></svg></div><div class="legend"><span><i style="background:var(--cs-chart-primary)"></i>Current run</span><span><i style="background:var(--cs-chart-comparison)"></i>Previous run · dashed</span><span><i style="background:var(--cs-peach)"></i>Above budget</span></div><label class="cs-label" for="chartLoad">Inspect a tested load: <output id="chartLoadValue">40 calls</output></label><input id="chartLoad" type="range" min="0" max="5" value="4" style="width:100%;accent-color:var(--cs-olive)"><div class="chart-takeaway" id="chartAnswer">At 40 calls, P95 reaches 1.18 s.</div><p class="cs-caption">600 synthetic calls · 100 per level · equally spaced tested steps</p><details><summary style="font-size:14px;cursor:pointer">View underlying values</summary>'''+rows([['Concurrent calls','Current P95','Previous P95']]+[[str(n),f'{a:.2f} s',f'{b:.2f} s'] for n,a,b in zip([1,5,10,20,40,80],[.55,.59,.63,.78,1.18,2.2],[.5,.53,.59,.7,1,1.94])])+'</details>'
body=heading('LINE CHART','How much traffic can the agent handle?','An ordered load sweep with a visible budget, a comparison, and a selectable observation.')+specimen('Latency stays within budget through 20 calls.',linechart,'P95 response time · seconds · lower is better')+heading('COMPARISON & COMPOSITION','Choose the chart that fits the question.')+'<div class="grid g2">'+specimen('Which scenario needs attention?',''.join(f'<div class="bar-row"><span>{name}</span><div class="bar-track"><div class="bar-fill" style="width:{v}%;'+('background:var(--cs-peach);border-color:var(--cs-chart-target)' if i==3 else '')+f'"></div></div><span>{v}%</span></div>' for i,(name,v) in enumerate([('Standard',97.6),('Escalation',96.4),('Noisy caller',94.4),('Interrupted',88.4)]))+'<div class="chart-takeaway">Interrupted refunds have the lowest success.</div><p class="cs-caption">Task success · bar scale 0–100% · 250 calls per scenario</p>')+specimen('Where does response time go?','<div class="segment-bar"><span style="width:19.512%;background:var(--cs-blue)">160</span><span style="width:58.537%;background:var(--cs-lavender)">480</span><span style="width:21.951%;background:var(--cs-peach)">180</span></div><div class="legend"><span>Endpointing</span><span>Model</span><span>Speech</span></div><div class="chart-takeaway">Model generation accounts for 58.5% of the wait.</div><p class="cs-caption">Mean stage durations · milliseconds · 820 ms total</p><p>Use additive means or one measured trace. Do not add stage percentiles.</p>')+'</div>'+heading('CHART TOKENS','Strong strokes, quiet fills, readable labels.')+swatches(['chart-primary','chart-comparison','chart-efficiency','chart-target'])+'<div class="grid g2" style="margin-top:20px">'+specimen('Use this anatomy','<ol class="rule-list"><li>A question the chart answers.</li><li>Measure, unit, and direction of improvement.</li><li>A plain-language takeaway.</li><li>A target or meaningful baseline.</li><li>Sample size and underlying evidence.</li></ol>')+specimen('Avoid these shortcuts','<ul class="rule-list"><li>Unlabeled axes or ambiguous units.</li><li>Color as the only distinction.</li><li>Percentile sums presented as stage totals.</li><li>Missing data silently replaced with zero.</li><li>Text that becomes tiny on mobile.</li></ul>')+'</div>'
